export type ParsedDriftWithdrawInstruction<
  TProgram extends string = typeof MARGINFI_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    group: TAccountMetas[0];
    marginfiAccount: TAccountMetas[1];
    authority: TAccountMetas[2];
    bank: TAccountMetas[3];
    /** The oracle account for the asset (not needed if using oracle type QuoteAsset) */
    driftOracle?: TAccountMetas[4] | undefined;
    /** The bank's liquidity vault authority, which owns the Drift user account */
    liquidityVaultAuthority: TAccountMetas[5];
    /** Receives tokens from Drift withdrawal */
    liquidityVault: TAccountMetas[6];
    /** Token account that will receive the withdrawn tokens */
    destinationTokenAccount: TAccountMetas[7];
    /** The Drift state account */
    driftState: TAccountMetas[8];
    /** The Drift user account owned by liquidity_vault_authority */
    integrationAcc2: TAccountMetas[9];
    /** The Drift user stats account owned by liquidity_vault_authority */
    integrationAcc3: TAccountMetas[10];
    /** The Drift spot market for this asset */
    integrationAcc1: TAccountMetas[11];
    /** The Drift spot market vault that holds tokens */
    driftSpotMarketVault: TAccountMetas[12];
    /** Optional: Oracle for first reward asset (only needed if rewards exist) */
    driftRewardOracle?: TAccountMetas[13] | undefined;
    /** Optional: Spot market for first reward asset (only needed if rewards exist) */
    driftRewardSpotMarket?: TAccountMetas[14] | undefined;
    /** Optional: Mint for first reward asset (only needed if rewards exist) */
    driftRewardMint?: TAccountMetas[15] | undefined;
    /** Optional: Oracle for second reward asset (backup in case multiple rewards) */
    driftRewardOracle2?: TAccountMetas[16] | undefined;
    /** Optional: Spot market for second reward asset (backup in case multiple rewards) */
    driftRewardSpotMarket2?: TAccountMetas[17] | undefined;
    /** Optional: Mint for second reward asset (backup in case multiple rewards) */
    driftRewardMint2?: TAccountMetas[18] | undefined;
    /** The Drift signer PDA */
    driftSigner: TAccountMetas[19];
    /** Bank's liquidity token mint */
    mint: TAccountMetas[20];
    driftProgram: TAccountMetas[21];
    tokenProgram: TAccountMetas[22];
    systemProgram: TAccountMetas[23];
  };
  data: DriftWithdrawInstructionData;
};

export function parseDriftWithdrawInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedDriftWithdrawInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 24) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 24,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === MARGINFI_PROGRAM_ADDRESS ? undefined : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      group: getNextAccount(),
      marginfiAccount: getNextAccount(),
      authority: getNextAccount(),
      bank: getNextAccount(),
      driftOracle: getNextOptionalAccount(),
      liquidityVaultAuthority: getNextAccount(),
      liquidityVault: getNextAccount(),
      destinationTokenAccount: getNextAccount(),
      driftState: getNextAccount(),
      integrationAcc2: getNextAccount(),
      integrationAcc3: getNextAccount(),
      integrationAcc1: getNextAccount(),
      driftSpotMarketVault: getNextAccount(),
      driftRewardOracle: getNextOptionalAccount(),
      driftRewardSpotMarket: getNextOptionalAccount(),
      driftRewardMint: getNextOptionalAccount(),
      driftRewardOracle2: getNextOptionalAccount(),
      driftRewardSpotMarket2: getNextOptionalAccount(),
      driftRewardMint2: getNextOptionalAccount(),
      driftSigner: getNextAccount(),
      mint: getNextAccount(),
      driftProgram: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getDriftWithdrawInstructionDataDecoder().decode(instruction.data),
  };
}
